class Solution:
    def longestPrefix(self, s):
        pi = [0] * len(s)
        j = 0
        for i in range(1, len(s)):
            while j and s[i] != s[j]:
                j = pi[j - 1]
            if s[i] == s[j]:
                j += 1
                pi[i] = j
        return s[:pi[-1]] if s else ""

